package pe.edu.upeu.notificacion.controller; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import pe.edu.upeu.notificacion.dto.*; import pe.edu.upeu.notificacion.service.NotificacionService; import java.util.*; @RestController @RequestMapping("/api/v1/notificaciones") @RequiredArgsConstructor public class NotificacionController{private final NotificacionService service;@GetMapping public List<NotificacionResponse>listar(){return service.listar();}@GetMapping("/usuario/{id}")public List<NotificacionResponse>usuario(@PathVariable Long id){return service.usuario(id);}@GetMapping("/usuario/{id}/no-leidas")public List<NotificacionResponse>noLeidas(@PathVariable Long id){return service.noLeidas(id);}@PutMapping("/{id}/leer")public NotificacionResponse leer(@PathVariable Long id){return service.leer(id);}}